import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../models/zaylo_models.dart';import '../../repositories/providers.dart';
class OutagesScreen extends ConsumerWidget{const OutagesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final data=ref.watch(mockRepositoryProvider).outages();return DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Outage Alerts'),bottom:const TabBar(tabs:[Tab(text:'Electricity'),Tab(text:'Water')])),floatingActionButton:FloatingActionButton.extended(onPressed:()=>showComingSoon(context,'Submit outage'),label:const Text('Submit'),icon:const Icon(Icons.add)),body:TabBarView(children:['Electricity','Water'].map((kind)=>ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(hintText:'Filter by city or area')),for(final o in data.where((x)=>x.kind==kind)) ZayloCard(child:ListTile(title:Text('${o.area}, ${o.city}'),subtitle:Text('Reported ${o.createdAt.hour}:30 • ${o.confirmations} confirmations'),trailing:TrustBadge(o.status==VerificationStatus.verified),onTap:()=>showComingSoon(context,'Confirm or mark restored')))] )).toList())));}}
